package org.apache.commons.lang.time;

import java.io.*;
import java.math.*;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.Iterator;
import java.util.NoSuchElementException;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class DateUtils_iterator_TriageGen2Test {

    // Constants based on the provided logic (assuming these exist in DateUtils)
    private static final int RANGE_MONTH_SUNDAY = 1;
    private static final int RANGE_MONTH_MONDAY = 2;
    private static final int RANGE_WEEK_SUNDAY = 3;
    private static final int RANGE_WEEK_MONDAY = 4;
    private static final int RANGE_WEEK_RELATIVE = 5;
    private static final int RANGE_WEEK_CENTER = 6;
    private static final int INVALID_RANGE = 99;

    @Test(expected = IllegalArgumentException.class)
    public void testIterator_NullFocus() {
        DateUtils.iterator(null, RANGE_MONTH_SUNDAY);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIterator_InvalidRangeStyle() {
        Calendar cal = Calendar.getInstance();
        DateUtils.iterator(cal, INVALID_RANGE);
    }

    @Test
    public void testIterator_RangeMonthSunday() {
        Calendar cal = Calendar.getInstance();
        cal.set(2023, Calendar.OCTOBER, 15); // A Sunday
        // MONTH_SUNDAY: start is 1st of month, then back to previous Sunday
        // end is last of month, then forward to next Saturday
        Iterator it = DateUtils.iterator(cal, RANGE_MONTH_SUNDAY);
        assertNotNull(it);
        assertTrue(it.hasNext());
    }

    @Test
    public void testIterator_RangeMonthMonday() {
        Calendar cal = Calendar.getInstance();
        cal.set(2023, Calendar.OCTOBER, 15);
        // MONTH_MONDAY: start is 1st of month, then back to previous Monday
        // end is last of month, then forward to next Sunday
        Iterator it = DateUtils.iterator(cal, RANGE_MONTH_MONDAY);
        assertNotNull(it);
        assertTrue(it.hasNext());
    }

    @Test
    public void testIterator_RangeWeekSunday() {
        Calendar cal = Calendar.getInstance();
        cal.set(2023, Calendar.OCTOBER, 15); // Sunday
        Iterator it = DateUtils.iterator(cal, RANGE_WEEK_SUNDAY);
        assertNotNull(it);
    }

    @Test
    public void testIterator_RangeWeekMonday() {
        Calendar cal = Calendar.getInstance();
        cal.set(2023, Calendar.OCTOBER, 15); // Sunday
        // Monday range: startCutoff=MONDAY, endCutoff=SUNDAY
        Iterator it = DateUtils.iterator(cal, RANGE_WEEK_MONDAY);
        assertNotNull(it);
    }

    @Test
    public void testIterator_RangeWeekRelative() {
        Calendar cal = Calendar.getInstance();
        cal.set(2023, Calendar.OCTOBER, 18); // Wednesday (DAY_OF_WEEK = 4)
        // startCutoff = 4, endCutoff = 3
        Iterator it = DateUtils.iterator(cal, RANGE_WEEK_RELATIVE);
        assertNotNull(it);
    }

    @Test
    public void testIterator_RangeWeekCenter() {
        Calendar cal = Calendar.getInstance();
        cal.set(2023, Calendar.OCTOBER, 18); // Wednesday (DAY_OF_WEEK = 4)
        // startCutoff = 4 - 3 = 1 (SUNDAY)
        // endCutoff = 4 + 3 = 7 (SATURDAY)
        Iterator it = DateUtils.iterator(cal, RANGE_WEEK_CENTER);
        assertNotNull(it);
    }

    /**
     * This test aims to trigger the boundary logic for startCutoff and endCutoff 
     * integer adjustments (e.g., < SUNDAY or > SATURDAY) if possible via logic paths.
     * Since Calendar.SUNDAY is 1 and SATURDAY is 7, the logic:
     * if (startCutoff < 1) startCutoff += 7;
     * if (startCutoff > 7) startCutoff -= 7;
     * is triggered by the relative/center logic.
     */
    @Test
    public void testIterator_CutoffBoundaryLogic() {
        Calendar cal = Calendar.getInstance();
        // Test specific day to ensure the math in startCutoff/endCutoff triggers the if-blocks
        // If DAY_OF_WEEK is 1 (Sunday):
        // RANGE_WEEK_CENTER: startCutoff = 1 - 3 = -2. 
        // -2 < 1 -> -2 + 7 = 5 (FRIDAY)
        cal.set(Calendar.DAY_OF_WEEK, Calendar.SUNDAY);
        Iterator it = DateUtils.iterator(cal, RANGE_WEEK_CENTER);
        assertNotNull(it);

        // If DAY_OF_WEEK is 7 (Saturday):
        // RANGE_WEEK_CENTER: endCutoff = 7 + 3 = 10.
        // 10 > 7 -> 10 - 7 = 3 (TUESDAY)
        cal.set(Calendar.DAY_OF_WEEK, Calendar.SATURDAY);
        Iterator it2 = DateUtils.iterator(cal, RANGE_WEEK_CENTER);
        assertNotNull(it2);
    }
}
